/****************************************************************************
 * Name:  sf32lb_lcd_async_wait
 *
 * Description:
 *   Block until the in-flight transfer (async or synchronous PUTAREA) has
 *   completed.  Safe to call when idle: returns immediately.  timeout_ms 0
 *   waits forever.
 *
 ****************************************************************************/

int sf32lb_lcd_async_wait(uint32_t timeout_ms)
{
  struct timespec ts;

  while (sf32lb_lcd_async_busy())
    {
      if (timeout_ms == 0)
        {
          if (sem_wait(&s_async_done_sem) < 0)
            {
              return -errno;
            }
        }
      else
        {
          clock_gettime(CLOCK_REALTIME, &ts);
          ts.tv_sec  += (time_t)(timeout_ms / 1000u);
          ts.tv_nsec += (long)(timeout_ms % 1000u) * 1000000L;
          if (ts.tv_nsec >= 1000000000L)
            {
              ts.tv_sec++;
              ts.tv_nsec -= 1000000000L;
            }

          if (sem_timedwait(&s_async_done_sem, &ts) < 0)
            {
              return errno == ETIMEDOUT ? -ETIMEDOUT : -errno;
            }
        }
    }

  return 0;
}


/****************************************************************************
 * Name:  sf32lb_lcd_putrun
 *
 * Description:
 *   This method can be used to write a partial raster line to the LCD:
 *
 *   dev     - The lcd device
 *   row     - Starting row to write to (range: 0 <= row < yres)
 *   col     - Starting column to write to (range: 0 <= col <= xres-npixels)
 *   buffer  - The buffer containing the run to be written to the LCD
 *   npixels - The number of pixels to write to the LCD
 *             (range: 0 < npixels <= xres-col)
 *
 ****************************************************************************/

static int sf32lb_lcd_putrun(FAR struct lcd_dev_s *dev,
                         fb_coord_t row, fb_coord_t col,
                         FAR const uint8_t *buffer, size_t npixels)
{
  FAR struct sf32lb_lcd_dev_s *priv = (FAR struct sf32lb_lcd_dev_s *)dev;

  if (s_fb_registering || !s_lcd_hw_ready)
    {
      return OK;
    }

  lcd_debug_print("row: %d col: %d npixels: %d\n", row, col, npixels);
  DEBUGASSERT(buffer && ((uintptr_t)buffer & 1) == 0);

  if (priv->bpp == 8)
    {
      FAR uint16_t *conv;
      size_t i;

      conv = kmm_malloc(npixels * sizeof(uint16_t));
      if (conv == NULL)
        {
          return -ENOMEM;
        }

      for (i = 0; i < npixels; i++)
        {
          uint8_t v = buffer[i];
          uint8_t r = (v >> 5) & 0x07;
          uint8_t g = (v >> 2) & 0x07;
          uint8_t b = v & 0x03;

